class Solution:
    def maxWeight(self, pizzas):
        pizzas.sort(reverse=True)
        d = len(pizzas) // 4
        return sum(pizzas[:(d + 1) // 2 + d // 2])

c.cpp:
class Solution {
public:
    long long maxWeight(vector<int>& pizzas) {
        sort(pizzas.rbegin(), pizzas.rend());
        int d = pizzas.size() / 4;
        long long ans = 0;
        int take = (d + 1) / 2 + d / 2;
        for (int i = 0; i < take; i++) ans += pizzas[i];
        return ans;
    }
};

c.java:
class Solution {
    public long maxWeight(int[] pizzas) {
        Arrays.sort(pizzas);
        int n = pizzas.length, d = n / 4;
        long ans = 0;
        int take = (d + 1) / 2 + d / 2;
        for (int i = 0; i < take; i++) ans += pizzas[n - 1 - i];
        return ans;
    }
}

