var maxWeight = function(pizzas) {
    pizzas.sort((a, b) => b - a);
    const d = pizzas.length / 4;
    let ans = 0;
    const take = Math.ceil(d / 2) + Math.floor(d / 2);
    for (let i = 0; i < take; i++) ans += pizzas[i];
    return ans;
};
